import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Install and connect","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/setup.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","filePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","lastUpdated":1791428389000}'),i={name:"packages/distant-horizons-support-pumpkin/docs/setup.md"};function o(r,e,l,p,c,d){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="install-and-connect" tabindex="-1">Install and connect <a class="header-anchor" href="#install-and-connect" aria-label="Permalink to &quot;Install and connect&quot;">​</a></h1><h2 id="check-client-compatibility" tabindex="-1">Check client compatibility <a class="header-anchor" href="#check-client-compatibility" aria-label="Permalink to &quot;Check client compatibility&quot;">​</a></h2><p>Before installing, check the plugin README for the supported Distant Horizons release and protocol. That README is generated from the plugin&#39;s compatibility metadata. Install the client mod separately on each Java Edition client. Bedrock players do not establish Distant Horizons sessions.</p><h2 id="install-the-server-plugin" tabindex="-1">Install the server plugin <a class="header-anchor" href="#install-the-server-plugin" aria-label="Permalink to &quot;Install the server plugin&quot;">​</a></h2><ol><li>Download the latest Distant Horizons Support plugin release.</li><li>Put <code>distant-horizons-support-pumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> folder.</li><li>Start or restart the server. The first load asks for the data-folder permissions listed in the generated plugin README. Approve them from the server console; a hot reload cannot show the permission prompt.</li><li>Connect with a compatible Java client. The plugin creates its settings file in its data folder on first load.</li></ol><p>The plugin README describes the current options, defaults and example config; these are generated from the configuration schema. Changes apply after a server restart. The plugin serves terrain that Pumpkin has already loaded or that the plugin has captured and cached before. Shared loading and generation provider interfaces are in place, but Pumpkin&#39;s current adapter reports those operations as unavailable.</p><p>The server negotiates generation and sync request limits independently and acknowledges client configuration updates. A nonzero client bandwidth setting limits outgoing server transfers; its credit bucket holds at most one full DH fragment message. Zero is unlimited. The generated README documents the current bounded queues and their provisional defaults.</p><p>Use the plugin&#39;s status and cache commands to check connected clients and cache usage after connecting.</p>',8)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
